using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public class LayerRulesTests
{
    private static readonly System.Reflection.Assembly Domain = typeof(Money).Assembly;
    private static readonly System.Reflection.Assembly Application = typeof(AuthorizePayment).Assembly;
    private static readonly System.Reflection.Assembly Infrastructure = typeof(HttpPaymentGateway).Assembly;

    // Technical namespaces the business layers must not touch.
    private static readonly string[] TechnicalDetails =
    [
        "System.IO", "System.Net", "System.Data", "System.Diagnostics.Process",
        "Microsoft.Data", "Microsoft.EntityFrameworkCore", "Microsoft.Extensions.Http",
    ];

    [Fact]
    public void Domain_does_not_depend_on_outer_layers() =>
        AssertNone(Types.InAssembly(Domain)
            .ShouldNot().HaveDependencyOnAny("PaymentAuthorization.Application", "PaymentAuthorization.Infrastructure"));

    [Fact]
    public void Application_does_not_depend_on_infrastructure() =>
        AssertNone(Types.InAssembly(Application)
            .ShouldNot().HaveDependencyOn("PaymentAuthorization.Infrastructure"));

    [Fact]
    public void Domain_does_not_use_technical_details() =>
        AssertNone(Types.InAssembly(Domain).ShouldNot().HaveDependencyOnAny(TechnicalDetails));

    [Fact]
    public void Application_does_not_use_technical_details() =>
        AssertNone(Types.InAssembly(Application).ShouldNot().HaveDependencyOnAny(TechnicalDetails));

    private static void AssertNone(ConditionList rule)
    {
        var result = rule.GetResult();
        Assert.True(result.IsSuccessful, "Violations: " + string.Join(", ", result.FailingTypeNames ?? []));
    }
}
EOF
